module multi_pipe_4bit (
    input clk,
    input rst_n,
    input [3:0] mul_a,
    input [3:0] mul_b,
    output [7:0] mul_out
);

    // Extension of input signals
    wire [7:0] mul_a_ext;
    wire [7:0] mul_b_ext;
    assign mul_a_ext = {4'b0000, mul_a};
    assign mul_b_ext = {4'b0000, mul_b};
    // Partial products generation
    wire [7:0] pp0, pp1, pp2, pp3;
    assign pp0 = (mul_b[0] ? mul_a_ext : 8'd0);
    assign pp1 = (mul_b[1] ? mul_a_ext << 1 : 8'd0);
    assign pp2 = (mul_b[2] ? mul_a_ext << 2 : 8'd0);
    assign pp3 = (mul_b[3] ? mul_a_ext << 3 : 8'd0);
    // Registers for storing intermediate results
    reg [7:0] sum_tmp1, sum_tmp2;
    // Register updates on positive edge of clk or negative edge of rst_n
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            sum_tmp1 <= 8'd0;
            sum_tmp2 <= 8'd0;
        end else begin
            sum_tmp1 <= pp0 + pp1;
            sum_tmp2 <= pp2 + pp3;
        end
    end

    // Final product calculation
    reg [7:0] mul_out_reg;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            mul_out_reg <= 8'd0;
        end else begin
            mul_out_reg <= sum_tmp1 + sum_tmp2;
        end
    end
    assign mul_out = mul_out_reg;
endmodule
